/**
 * M5/issue-13 Activity: executeNode. Delivers one message to one live node
 * and returns what that node actually sent, as {port, destinationId, msg}.
 *
 * `destinationId` is Node-RED's OWN resolved routing decision, captured by
 * Capture's `preRoute` hook (one event per actual wired destination - see
 * capture.js). Preserving it through the Activity boundary (issue #13)
 * lets the Workflow enqueue exactly those captured destinations without
 * re-deriving them from the raw wire graph, so Node-RED - not
 * node-red-temporal - remains the authority for what a send actually
 * routed to (fan-out, multiple sends on the same port, etc. all fall out
 * of this for free, since Capture already records one entry per resolved
 * destination).
 *
 * Framework-agnostic: no @temporalio/* here. `createExecuteNode` is a plain
 * DI factory - it closes over a bootstrapped flow handle and an installed
 * Capture instance, and returns the exact {flowVersion, nodeId, msg} ->
 * {sends, error?} function M6 hands to Temporal's Activity registration.
 */

"use strict";

const { isStockHttpResponse, createResponseRecorder } = require("./httpNodeBridge");

function mapSends(sends) {
    return (sends || []).map((s) => ({ port: s.port, destinationId: s.destinationId, msg: s.msg }));
}

function createExecuteNode({ getNode, flowVersion, capture, onHttpResponse }) {
    return async function executeNode({ flowVersion: requestedFlowVersion, nodeId, msg, httpBridge, httpBridgeId }) {
        // issue #15: `flowVersion` may be a live getter (function),
        // re-evaluated on EVERY Activity execution against Node-RED's
        // CURRENT runtime/deployment version, not a scalar closed over once
        // at Worker-boot time - so a `bootstrap().deploy()` redeploy that
        // happens between Activity executions is caught here, not silently
        // ignored.
        const currentFlowVersion = typeof flowVersion === "function" ? flowVersion() : flowVersion;
        if (requestedFlowVersion !== currentFlowVersion) {
            const error = {
                code: "FLOW_VERSION_MISMATCH",
                nodeId,
                message: `flowVersion mismatch: requested ${requestedFlowVersion}, current ${currentFlowVersion}`,
                sends: []
            };
            return { sends: [], error };
        }

        const node = getNode(nodeId);
        if (!node) {
            const error = {
                code: "NODE_NOT_FOUND",
                nodeId,
                message: `no node found for id ${nodeId}`,
                sends: []
            };
            return { sends: [], error };
        }

        // issue #75: when this Activity call is part of an HTTP-bridge
        // Workflow AND the node being invoked is the real stock "http
        // response" node, inject a small Activity-local response recorder
        // in place of the (never-transported) live Express response - see
        // httpNodeBridge.js's docblock. The recorder is scoped to this one
        // invocation only and never leaks across the Activity boundary;
        // only its plain, serializable descriptor does (via
        // `response.httpResponse` below).
        const recorderEntry = (httpBridge && isStockHttpResponse(node)) ? createResponseRecorder() : null;
        const nodeMsg = recorderEntry ? Object.assign({}, msg, { res: { _res: recorderEntry.res } }) : msg;

        try {
            const result = await capture.around(node, nodeMsg, () => node.receive(nodeMsg));
            const response = { sends: mapSends(result.sends) };
            if (recorderEntry) {
                response.httpResponse = recorderEntry.toDescriptor();
                // issue #82: optional early-response notification hook. Only
                // ever invoked for the stock HTTP Response node under an
                // HTTP-bridge run, and ONLY when the caller injected one AND
                // a bridge id came through on the input - this is purely an
                // optimization for the process that also owns the live
                // socket (worker.js's process-local registry); the
                // descriptor above is ALWAYS still returned normally
                // regardless of whether this hook exists, fires, or throws.
                // No @temporalio/activity dependency: this file stays
                // framework-agnostic and the bridge id is plain input data,
                // not rediscovered Activity Context.
                if (httpBridgeId && typeof onHttpResponse === "function") {
                    try {
                        onHttpResponse(httpBridgeId, response.httpResponse);
                    } catch (notifyErr) {
                        console.error(`[node-red-temporal] activities: onHttpResponse notify failed for httpBridgeId=${httpBridgeId}: ${notifyErr && notifyErr.message ? notifyErr.message : notifyErr}`);
                    }
                }
            }
            // issue #32: `result.handledError` is only ever set when
            // Node-RED's own error handling ALSO routed this error to a
            // wired Catch node (see capture.js `_settleError`'s `handled`
            // param) - the invocation still resolved (not rejected), so
            // `response.error` stays absent and the Workflow simply
            // continues draining `response.sends` like any ordinary
            // successful invocation. Carried through purely for
            // observability; no caller is required to inspect it.
            if (result.handledError) {
                response.handledError = {
                    code: "NODE_ERROR",
                    nodeId: result.handledError.nodeId,
                    message: String(result.handledError.error.message || result.handledError.error)
                };
            }
            return response;
        } catch (rejection) {
            const error = {
                code: rejection.timeout ? "NODE_TIMEOUT" : "NODE_ERROR",
                nodeId: rejection.nodeId || nodeId,
                message: rejection.error ? String(rejection.error.message || rejection.error) : "unknown node error",
                sends: mapSends(rejection.sends)
            };
            return { sends: mapSends(rejection.sends), error };
        }
    };
}

module.exports = { createExecuteNode };
